#include <bits/stdc++.h>
using namespace std;

string solveOne(int n, const string& s) {
    // rightCnt 统计当前位右侧尚未处理的原始字符数量
    vector<int> rightCnt(26, 0);
    for (char ch : s) {
        rightCnt[ch - 'a']++;
    }

    // leftCnt 统计左侧已确定的最终字符数量
    vector<int> leftCnt(26, 0);

    string ans;
    ans.reserve(n);

    for (char ch : s) {
        int idx = ch - 'a';

        // 当前字符即将被处理，不再属于右侧，先减去
        rightCnt[idx]--;

        int L = leftCnt[idx];
        int R = rightCnt[idx];

        int newIdx;
        if (L == R) {
            newIdx = (idx + 1) % 26;   // 字母表循环
        } else {
            newIdx = idx;
        }

        ans.push_back(char('a' + newIdx));
        // 最终字符计入左侧
        leftCnt[newIdx]++;
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n;
        string s;
        cin >> n >> s;
        cout << solveOne(n, s) << '\n';
    }

    return 0;
}
